entries[22568] = { ["name"] = "Wilder Biss", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden pro Combopunkt verursacht und vorhandene Energiepunkte (bis zu maximal 30) in jeweils (0.699999988 + Attack power / 410) zusätzlichen Schaden umwandelt. Schaden wird durch Angriffskraft erhöht.\n1 Punkt: (14 + 36 * 1 + 0.07 * Attack power)-(30 + 36 * 1 + 0.07 * Attack power) Schaden\n2 Punkte: (14 + 36 * 2 + 0.14 * Attack power)-(30 + 36 * 2 + 0.14 * Attack power) Schaden\n3 Punkte: (14 + 36 * 3 + 0.21 * Attack power)-(30 + 36 * 3 + 0.21 * Attack power) Schaden\n4 Punkte: (14 + 36 * 4 + 0.28 * Attack power)-(30 + 36 * 4 + 0.28 * Attack power) Schaden\n5 Punkte: (14 + 36 * 5 + 0.35 * Attack power)-(30 + 36 * 5 + 0.35 * Attack power) Schaden" }
entries[22570] = { ["name"] = "Zerfleddern", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nFinishing-Move, der Schaden verursacht und den Gegner betäubt. Unterbricht zudem 3 sec lang das Zauberwirken von Nichtspieler-Zielen. Verursacht mehr Schaden und hält pro Combopunkt länger an:\n1 Punkt: (84 * 1 + 45 + Mainhand weapon min damage)-(84 * 1 + 45 + Mainhand weapon max damage) Schaden, 1 Sek.\n2 Punkte: (84 * 2 + 45 + Mainhand weapon min damage)-(84 * 2 + 45 + Mainhand weapon max damage) Schaden, 2 Sek.\n3 Punkte: (84 * 3 + 45 + Mainhand weapon min damage)-(84 * 3 + 45 + Mainhand weapon max damage) Schaden, 3 Sek.\n4 Punkte: (84 * 4 + 45 + Mainhand weapon min damage)-(84 * 4 + 45 + Mainhand weapon max damage) Schaden, 4 Sek.\n5 Punkte: (84 * 5 + 45 + Mainhand weapon min damage)-(84 * 5 + 45 + Mainhand weapon max damage) Schaden, 5 Sek." }
