entries[23069] = { ["name"] = "EZ-Thro-Dynamit II", ["text"] = "Wirken in 2 sek.\nReagenzien:\nRobustes Sprengpulver , Magiestoff (2)\n30\nBenutzen: Fügt 213 to 287 Feuerschaden in einem Radius von 5 Metern zu (sollte es das Ziel treffen; es gelten Beschränkungen). (1 Min Abklingzeit)\n\"Das Dynamit für jedermann, das selten* in der Hand hochgeht, mit mehr als der doppelten Sprengkraft von einfachem EZ-Thro.\"" }
