entries[23078] = { ["name"] = "Goblinüberbrückungskabel XL", ["text"] = "Wirken in 12.5 sek.\nReagenzien:\nThoriumapparat (2), Echtsilberumwandler (2), Verschmorte Verkabelung (2), Eisenweberseide (2), Sternrubin (2)\nBenötigt Ingenieurskunst\n(265)\nBenutzen: Mit Überbrückungskabeln kann man manchmal einen toten Spieler ins Leben zurückrufen. Kann nicht im Kampf verwendet werden. (30 Min Abklingzeit)" }
